//! The ishikawa renderer's fixture test and the behavior the renderer pins beyond the
//! fixtures.
//!
//! The fixtures under `src/diagrams/ishikawa/tests/render/` are generated by the workspace's
//! upstream harness (`research/mermaid-port/harness/generate-ishikawa-render-fixtures.mjs`),
//! which renders each source through `mermaid.render` under jsdom and records the geometry the
//! SVG holds: every line, the head path, every label box and text (with its resolved anchor,
//! baseline, font size and measured box), the arrow marker, and the viewBox. The comparison
//! tolerance is 0.01px, the renderer's own precision.

use super::*;
use crate::scene::{PathCommand, Transform};
use serde_json::{Value, json};

const TOLERANCE: f64 = 0.01;

fn fixtures() -> Vec<(String, Value)> {
    let dir =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src/diagrams/ishikawa/tests/render");
    let mut fixtures: Vec<(String, Value)> = std::fs::read_dir(&dir)
        .unwrap_or_else(|error| panic!("read {}: {error}", dir.display()))
        .map(|entry| entry.expect("dir entry").path())
        .filter(|path| path.extension().and_then(|extension| extension.to_str()) == Some("json"))
        .map(|path| {
            let text = std::fs::read_to_string(&path).expect("read fixture");
            let value: Value = serde_json::from_str(&text).expect("parse fixture");
            (
                path.file_name()
                    .and_then(|name| name.to_str())
                    .unwrap_or_default()
                    .to_string(),
                value,
            )
        })
        .collect();
    fixtures.sort_by(|a, b| a.0.cmp(&b.0));
    fixtures
}

fn close(actual: f64, expected: f64, what: &str, file: &str) {
    assert!(
        (actual - expected).abs() <= TOLERANCE,
        "{file}: {what}: actual {actual} vs expected {expected}"
    );
}

fn close_value(actual: &Value, expected: &Value, what: &str, file: &str) {
    match (actual, expected) {
        (Value::Number(actual), Value::Number(expected)) => close(
            actual.as_f64().expect("number"),
            expected.as_f64().expect("number"),
            what,
            file,
        ),
        (Value::Array(actual), Value::Array(expected)) => {
            assert_eq!(actual.len(), expected.len(), "{file}: {what}: length");
            for (index, (actual, expected)) in actual.iter().zip(expected).enumerate() {
                close_value(actual, expected, &format!("{what}[{index}]"), file);
            }
        }
        (Value::Object(actual), Value::Object(expected)) => {
            assert_eq!(actual.len(), expected.len(), "{file}: {what}: keys");
            for (key, expected) in expected {
                close_value(
                    actual.get(key).unwrap_or(&Value::Null),
                    expected,
                    &format!("{what}.{key}"),
                    file,
                );
            }
        }
        _ => assert_eq!(actual, expected, "{file}: {what}"),
    }
}

fn anchor_name(anchor: TextAnchor) -> &'static str {
    match anchor {
        TextAnchor::Start => "start",
        TextAnchor::Middle => "middle",
        TextAnchor::End => "end",
    }
}

fn baseline_name(baseline: TextBaseline) -> &'static str {
    match baseline {
        TextBaseline::Alphabetic => "alphabetic",
        TextBaseline::Middle => "middle",
        TextBaseline::Hanging => "hanging",
        TextBaseline::Central => "central",
        TextBaseline::Top => "top",
        TextBaseline::Bottom => "bottom",
    }
}

fn color_name(color: &Option<Color>) -> Value {
    match color {
        Some(color) => json!(color.0),
        None => Value::Null,
    }
}

fn shift_point_value(value: &mut Value, transform: Transform) {
    if let Value::Object(map) = value {
        for key in ["x", "cx", "c1x", "c2x"] {
            if let Some(Value::Number(number)) = map.get_mut(key) {
                *number =
                    serde_json::Number::from_f64(number.as_f64().expect("number") + transform.e)
                        .expect("finite");
            }
        }
        for key in ["y", "cy", "c1y", "c2y"] {
            if let Some(Value::Number(number)) = map.get_mut(key) {
                *number =
                    serde_json::Number::from_f64(number.as_f64().expect("number") + transform.f)
                        .expect("finite");
            }
        }
    }
}

fn path_commands(path: &Path, transform: Transform) -> Value {
    Value::Array(
        path.commands
            .iter()
            .map(|command| {
                let mut value = serde_json::to_value(command).expect("serialize command");
                shift_point_value(&mut value, transform);
                value
            })
            .collect(),
    )
}

fn transform_rect(rect: Rect, transform: Transform) -> Rect {
    let top_left = transform.apply(Point::new(rect.x, rect.y));
    Rect::new(top_left.x, top_left.y, rect.width, rect.height)
}

fn line_endpoints(shape: &PathShape) -> Option<(f64, f64, f64, f64)> {
    let [
        PathCommand::MoveTo { x: x1, y: y1 },
        PathCommand::LineTo { x: x2, y: y2 },
    ] = shape.path.commands.as_slice()
    else {
        return None;
    };
    Some((*x1, *y1, *x2, *y2))
}

fn actual_leaves(items: &[Item], transform: Transform, out: &mut Vec<Value>) {
    for item in items {
        match item {
            Item::Group(group) => {
                actual_leaves(&group.items, transform.then(group.transform), out);
            }
            Item::Path(shape) => {
                if let Some((x1, y1, x2, y2)) = line_endpoints(shape) {
                    let start = transform.apply(Point::new(x1, y1));
                    let end = transform.apply(Point::new(x2, y2));
                    out.push(json!({
                        "kind": "line",
                        "x1": start.x,
                        "y1": start.y,
                        "x2": end.x,
                        "y2": end.y,
                        "stroke": color_name(&shape.style.stroke),
                        "strokeWidth": shape.style.stroke_width,
                        "markerStart": if shape.start_markers.is_empty() {
                            Value::Null
                        } else {
                            json!(shape.start_markers[0].def)
                        },
                    }));
                } else {
                    out.push(json!({
                        "kind": "path",
                        "commands": path_commands(&shape.path, transform),
                        "fill": color_name(&shape.style.fill),
                        "stroke": color_name(&shape.style.stroke),
                        "strokeWidth": shape.style.stroke_width,
                    }));
                }
            }
            Item::Rect(shape) => {
                let rect = transform_rect(shape.rect, transform);
                out.push(json!({
                    "kind": "rect",
                    "x": rect.x,
                    "y": rect.y,
                    "width": rect.width,
                    "height": rect.height,
                    "fill": color_name(&shape.style.fill),
                    "stroke": color_name(&shape.style.stroke),
                    "strokeWidth": shape.style.stroke_width,
                }));
            }
            Item::Text(run) => {
                let position = transform.apply(run.position);
                let bounds = transform_rect(run.bounds(), transform);
                out.push(json!({
                    "kind": "text",
                    "lines": run.lines.iter().map(|line| line.text()).collect::<Vec<_>>(),
                    "x": position.x,
                    "y": position.y,
                    "anchor": anchor_name(run.anchor),
                    "baseline": baseline_name(run.baseline),
                    "fontSize": run.font.size,
                    "lineHeight": if run.lines.len() > 1 {
                        json!(run.line_height)
                    } else {
                        Value::Null
                    },
                    "fill": color_name(&run.fill),
                    "box": {
                        "x": bounds.x,
                        "y": bounds.y,
                        "width": bounds.width,
                        "height": bounds.height,
                    },
                }));
            }
            Item::Ellipse(_) | Item::Image(_) => {
                panic!("the ishikawa renderer draws no ellipse or image")
            }
        }
    }
}

/// The expected item without its CSS class, which a [`Scene`] leaf does not carry.
fn without_class(expected: &Value) -> Value {
    match expected {
        Value::Object(map) => {
            let mut map = map.clone();
            map.remove("class");
            map.remove("d");
            Value::Object(map)
        }
        other => other.clone(),
    }
}

/// The expected marker without its `d` string, which the command list already spells out.
fn without_path_string(expected: &Value) -> Value {
    match expected {
        Value::Object(map) => {
            let mut map = map.clone();
            map.remove("d");
            Value::Object(map)
        }
        other => other.clone(),
    }
}

fn actual_marker(def: &MarkerDef) -> Value {
    let first = def.shapes.first().expect("the arrow marker has a shape");
    json!({
        "id": def.id,
        "viewBox": {
            "x": def.view_box.x,
            "y": def.view_box.y,
            "width": def.view_box.width,
            "height": def.view_box.height,
        },
        "reference": { "x": def.reference.x, "y": def.reference.y },
        "width": def.width,
        "height": def.height,
        "orient": match def.orient {
            MarkerOrient::Auto => "auto",
            MarkerOrient::AutoStartReverse => "auto-start-reverse",
            MarkerOrient::Fixed { .. } => "fixed",
        },
        "class": def.class,
        "commands": path_commands(&first.path, Transform::IDENTITY),
        "fill": color_name(&first.style.fill),
    })
}

#[test]
fn renders_recorded_ishikawa_fixtures() {
    let fixtures = fixtures();
    assert!(
        fixtures.len() >= 8,
        "expected at least 8 fixtures, found {}",
        fixtures.len()
    );

    for (file, fixture) in fixtures {
        let source = fixture["source"].as_str().expect("fixture source");
        let preprocessed = crate::preprocess::preprocess(source);
        let config = Config::from_source_config(&preprocessed.config)
            .unwrap_or_else(|error| panic!("{file}: config: {error}"));
        let ast = super::super::parse(&preprocessed.body)
            .unwrap_or_else(|error| panic!("{file}: parse: {error}"));
        let scene = draw_ast(&ast, &config, &crate::measure::FallbackMeasure);
        let expected = &fixture["expected"];

        let expected_view_box = &expected["viewBox"];
        close(
            scene.view_box.x,
            expected_view_box["x"].as_f64().expect("viewBox x"),
            "viewBox x",
            &file,
        );
        close(
            scene.view_box.y,
            expected_view_box["y"].as_f64().expect("viewBox y"),
            "viewBox y",
            &file,
        );
        close(
            scene.view_box.width,
            expected_view_box["width"].as_f64().expect("viewBox width"),
            "viewBox width",
            &file,
        );
        close(
            scene.view_box.height,
            expected_view_box["height"]
                .as_f64()
                .expect("viewBox height"),
            "viewBox height",
            &file,
        );

        let expected_markers = expected["markers"].as_array().expect("markers");
        assert_eq!(scene.defs.len(), expected_markers.len(), "{file}: markers");
        for (def, expected_marker) in scene.defs.iter().zip(expected_markers) {
            close_value(
                &actual_marker(def),
                &without_path_string(expected_marker),
                "marker",
                &file,
            );
        }

        let mut leaves = Vec::new();
        actual_leaves(&scene.items, Transform::IDENTITY, &mut leaves);
        let expected_leaves = expected["items"].as_array().expect("items");
        assert_eq!(leaves.len(), expected_leaves.len(), "{file}: item count");
        for (index, (actual, expected)) in leaves.iter().zip(expected_leaves).enumerate() {
            close_value(
                actual,
                &without_class(expected),
                &format!("item {index}"),
                &file,
            );
        }
    }
}

#[test]
fn draws_a_head_and_a_point_spine_for_a_root_without_causes() {
    let scene = render("ishikawa\n  Nothing underneath\n", &Config::default()).expect("render");
    let expected = &fixtures()
        .into_iter()
        .find(|(file, _)| file == "13-no-causes.json")
        .expect("no-causes fixture")
        .1["expected"];
    let mut leaves = Vec::new();
    actual_leaves(&scene.items, Transform::IDENTITY, &mut leaves);
    assert_eq!(
        leaves.len(),
        expected["items"].as_array().expect("items").len()
    );
    close(
        scene.view_box.width,
        expected["viewBox"]["width"].as_f64().expect("width"),
        "viewBox width",
        "13-no-causes.json",
    );
}

#[test]
fn an_empty_database_draws_nothing() {
    let scene = render("ishikawa\n  %% only a comment\n", &Config::default()).expect("render");
    assert!(scene.items.is_empty());
    assert_eq!(scene.view_box, Rect::ZERO);
}

#[test]
fn render_diagram_dispatches_ishikawa() {
    let scene = crate::render_diagram("ishikawa\n  Effect\n    Cause\n", &Config::default())
        .expect("dispatch ishikawa");
    assert_eq!(scene.items.len(), 1);
    assert_eq!(
        scene.defs.first().map(|def| def.id.as_str()),
        Some(MARKER_ID)
    );
}

#[test]
fn render_diagram_removes_a_comment_between_statements() {
    // An empty line between statements makes the grammar fail, so the comment line must go
    // whole rather than leave one behind.
    let with_comment = "ishikawa\n  Effect\n  %% the cause follows\n    Cause\n";
    let without_comment = "ishikawa\n  Effect\n    Cause\n";
    let drawn = crate::render_diagram(with_comment, &Config::default())
        .expect("dispatch ishikawa with a comment");
    let expected = crate::render_diagram(without_comment, &Config::default())
        .expect("dispatch ishikawa without a comment");
    assert_eq!(drawn, expected);
}

#[test]
fn rejects_text_that_is_not_an_ishikawa_diagram() {
    let error = render("requirementDiagram\n", &Config::default()).unwrap_err();
    assert!(matches!(error, IshikawaRenderError::Parse(_)));
}

#[test]
fn wraps_text_greedily_like_upstream() {
    assert_eq!(wrap_text("short", 15), "short");
    assert_eq!(
        wrap_text("Supplier delays during the holiday season", 15),
        "Supplier delays\nduring the\nholiday season"
    );
    assert_eq!(
        wrap_text("Deadlines are always too tight", 15),
        "Deadlines are\nalways too\ntight"
    );
}

#[test]
fn splits_br_tags_and_newlines_into_rows() {
    assert_eq!(split_lines("a<br>b\nc<br />d"), vec!["a", "b", "c", "d"]);
    assert_eq!(split_lines("a<BR>b"), vec!["a<BR>b"]);
    assert_eq!(split_lines("plain"), vec!["plain"]);
}
